namespace BlazorApp.Models;

public class EquipmentItem
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Location { get; set; } = string.Empty;
    public DateTime LastInspected { get; set; }
}

using BlazorApp.Models;

namespace BlazorApp.Services;

public class EquipmentService
{
    public async Task<List<EquipmentItem>> GetEquipmentAsync()
    {
        // Simulate network/database latency
        await Task.Delay(500);

        return new List<EquipmentItem>
        {
            new() { Id = 1, Name = "Forklift A", Location = "Warehouse 1", LastInspected = new DateTime(2026, 5, 12) },
            new() { Id = 2, Name = "Crane B", Location = "Yard 3", LastInspected = new DateTime(2026, 4, 28) },
            new() { Id = 3, Name = "Compressor C", Location = "Building 2", LastInspected = new DateTime(2026, 3, 15) },
            new() { Id = 4, Name = "Drill Press D", Location = "Workshop 1", LastInspected = new DateTime(2026, 6, 1) },
            new() { Id = 5, Name = "Lathe E", Location = "Workshop 2", LastInspected = new DateTime(2026, 2, 20) },
            new() { Id = 6, Name = "Welder F", Location = "Bay 4", LastInspected = new DateTime(2026, 5, 30) },
            new() { Id = 7, Name = "Generator G", Location = "Utility Room", LastInspected = new DateTime(2026, 1, 10) },
            new() { Id = 8, Name = "Pump H", Location = "Basement", LastInspected = new DateTime(2026, 4, 5) },
        };
    }
}

@page "/inventory"
@rendermode InteractiveServer
@attribute [StreamRendering]
@using BlazorApp.Models
@using BlazorApp.Services
@inject EquipmentService EquipmentService
@inject PersistentComponentState ApplicationState
@implements IDisposable

<PageTitle>Inventory</PageTitle>

<h1>Equipment Inventory</h1>

@if (_items is null)
{
    <p><em>Loading inventory...</em></p>
}
else
{
    <table class="table">
        <thead>
            <tr>
                <th>Id</th>
                <th>Name</th>
                <th>Location</th>
                <th>Last Inspected</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var item in _items)
            {
                <tr>
                    <td>@item.Id</td>
                    <td>@item.Name</td>
                    <td>@item.Location</td>
                    <td>@item.LastInspected.ToShortDateString()</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<EquipmentItem>? _items;
    private PersistingComponentStateSubscription _persistingSubscription;

    protected override async Task OnInitializedAsync()
    {
        _persistingSubscription = ApplicationState.RegisterOnPersisting(PersistData);

        // If data was persisted during prerender, reuse it instead of fetching again.
        if (ApplicationState.TryTakeFromJson<List<EquipmentItem>>("inventory", out var restored))
        {
            _items = restored;
        }
        else
        {
            _items = await EquipmentService.GetEquipmentAsync();
        }
    }

    private Task PersistData()
    {
        ApplicationState.PersistAsJson("inventory", _items);
        return Task.CompletedTask;
    }

    public void Dispose()
    {
        _persistingSubscription.Dispose();
    }
}

